import sqlite3
import os
from flask import Flask, request, jsonify, g
import hashlib
import hmac

app = Flask(__name__)
DATABASE = '/var/data/users.db'
SECRET_KEY = os.environ.get('HMAC_SECRET', 'default-dev-key')

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE,
        email TEXT,
        role TEXT DEFAULT 'user',
        api_key TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        user_id INTEGER,
        details TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    db.execute("INSERT OR IGNORE INTO users (id, username, email, role, api_key) VALUES (1, 'admin', 'admin@corp.internal', 'admin', 'ak_prod_9f8e7d6c5b4a')")
    db.execute("INSERT OR IGNORE INTO users (id, username, email, role, api_key) VALUES (2, 'svc-reader', 'reader@corp.internal', 'readonly', 'ak_prod_1a2b3c4d5e6f')")
    db.commit()
    db.close()

def verify_request_signature(req):
    """Verify HMAC signature for write operations"""
    sig = req.headers.get('X-Request-Signature')
    if not sig:
        return False
    body = req.get_data()
    expected = hmac.new(SECRET_KEY.encode(), body, hashlib.sha256).hexdigest()
    return hmac.compare_digest(sig, expected)

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

@app.route('/api/v2/users/search', methods=['GET'])
def search_users():
    """Search users by various fields. Supports partial matching."""
    field = request.args.get('field', 'username')
    value = request.args.get('q', '')

    # Validate field name against allowed columns
    allowed_fields = ['username', 'email', 'role']
    if field not in allowed_fields:
        return jsonify({'error': 'Invalid search field'}), 400

    if not value or len(value) > 100:
        return jsonify({'error': 'Invalid query parameter'}), 400

    # Log the search for audit purposes
    app.logger.info(f"User search: field={field}, query={value}")

    # Build query with validated field name but user-supplied value
    query = f"SELECT id, username, email, role FROM users WHERE {field} LIKE '%{value}%'"

    try:
        db = get_db()
        cursor = db.execute(query)
        results = [dict(row) for row in cursor.fetchall()]
        return jsonify({'results': results, 'count': len(results)})
    except sqlite3.Error as e:
        app.logger.error(f"Database error: {e}")
        return jsonify({'error': 'Search failed'}), 500

@app.route('/api/v2/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    """Get user details by ID"""
    db = get_db()
    cursor = db.execute("SELECT id, username, email, role FROM users WHERE id = ?", (user_id,))
    user = cursor.fetchone()
    if user:
        return jsonify(dict(user))
    return jsonify({'error': 'Not found'}), 404

@app.route('/api/v2/users', methods=['POST'])
def create_user():
    """Create a new user - requires valid request signature"""
    if not verify_request_signature(request):
        return jsonify({'error': 'Invalid signature'}), 403
    data = request.get_json()
    if not data or 'username' not in data:
        return jsonify({'error': 'Missing required fields'}), 400
    db = get_db()
    try:
        db.execute(
            "INSERT INTO users (username, email, role) VALUES (?, ?, ?)",
            (data['username'], data.get('email', ''), 'user')
        )
        db.commit()
        return jsonify({'status': 'created'}), 201
    except sqlite3.IntegrityError:
        return jsonify({'error': 'User already exists'}), 409

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'healthy', 'version': '2.4.1'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
